{
  "findings": [
    {
      "ref": "[D523]",
      "area": "age_gating",
      "claim": "A parent reports that Snapchat's age verification is minimal and relies only on a birth date at signup with no real checks.",
      "stance": "risk",
      "quote": "Snapchat requires users to be at least 13 years old, but it's actually required to under U.S. privacy laws (COPPA). In reality, Snapchat's age verification is minimal. It only asks for a birth date at signup, with no real checks behind it."
    },
    {
      "ref": "[D523]",
      "area": "age_gating",
      "claim": "A parent reports that kids can easily fake their age to join Snapchat early.",
      "stance": "risk",
      "quote": "Kids who want to join early can easily fake their age—and many do."
    },
    {
      "ref": "[D523]",
      "area": "age_gating",
      "claim": "A parent reports that Snapchat locks in the original birth date after signup, preventing users from editing it to bypass protections.",
      "stance": "mitigation",
      "quote": "Snapchat also locks in the original birth date after teens sign up, so they can't edit it later to \"age up\" and bypass protections."
    },
    {
      "ref": "[D523]",
      "area": "contact",
      "claim": "A parent reports that strangers can message teens unless the teen has added them as a friend, and this can be turned off by setting 'Who Can Contact Me' to 'My Friends'.",
      "stance": "risk",
      "quote": "Only friends they've added can send them direct messages."
    },
    {
      "ref": "[D523]",
      "area": "contact",
      "claim": "A parent reports that Quick Add can suggest friends to teens, and this can be disabled to limit random friend requests.",
      "stance": "mitigation",
      "quote": "They won't appear in Quick Add recommendations for people they don't know, which helps limit random friend requests."
    },
    {
      "ref": "[D523]",
      "area": "content",
      "claim": "A parent reports that Discover and Spotlight content is filtered for teens aged 13–15, but filters are not always perfect.",
      "stance": "risk",
      "quote": "Content in Discover and Spotlight is filtered to reduce exposure to mature or inappropriate material, but filters are not always perfect."
    },
    {
      "ref": "[D523]",
      "area": "content",
      "claim": "A parent reports that public Stories for teens aged 16–17 are mostly visible to friends and mutual connections, not the wider community.",
      "stance": "mitigation",
      "quote": "They can post public Stories, but these mostly show up for friends and mutual connections, not the wider Snapchat community."
    },
    {
      "ref": "[D523]",
      "area": "money",
      "claim": "A parent reports that Snapchat offers a monetization program for creators, which may pressure teens to spend more time curating content.",
      "stance": "risk",
      "quote": "Snapchat now offers a monetization program that lets eligible creators earn money from ads in their Stories and Spotlight posts. Teens who see influencers getting paid for views may feel pressure to post more often, chase viral moments, or spend more time curating content to stand out."
    },
    {
      "ref": "[D523]",
      "area": "data",
      "claim": "A parent reports that Snapchat collects data for ads and may share it with third parties, but the policy does not specify deletion options.",
      "stance": "risk",
      "quote": "Snapchat collects data for advertising and may share it with partners, though the exact data handling and deletion mechanisms are not detailed in the provided text."
    }
  ]
}
